/**
 * ReschedulePopover — Compact inline date picker for rescheduling a repair.
 *
 * Renders an absolute-positioned popover with:
 * - Date input pre-filled with the repair's anchor date (plannedDate or createdAt)
 * - Confirm button that PATCHes plannedDate via updateRepairNotes API
 * - Cancel button that closes without saving
 *
 * The caller controls `open` state and provides callbacks for confirm/cancel.
 */

import { useState, useEffect } from 'react'
import type { RepairDetailWithCustomer } from '../types.js'
import { getDateAnchor } from '../utils/dateAnchor.js'
import { updateRepairNotes } from '../api.js'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface ReschedulePopoverProps {
  repair: RepairDetailWithCustomer
  open: boolean
  onConfirm: () => void
  onCancel: () => void
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Convert epoch-ms to YYYY-MM-DD string for HTML date input */
function epochToDateInput(epochMs: number): string {
  const d = new Date(epochMs)
  return d.toISOString().split('T')[0]
}

/** Parse YYYY-MM-DD from date input to epoch-ms (start of day, local time) */
function dateInputToEpoch(value: string): number | null {
  if (!value) return null
  const parts = value.split('-')
  if (parts.length !== 3) return null
  // Create date in local timezone to avoid UTC shift issues
  const year = parseInt(parts[0], 10)
  const month = parseInt(parts[1], 10) - 1 // JS months are 0-indexed
  const day = parseInt(parts[2], 10)
  const d = new Date(year, month, day)
  if (isNaN(d.getTime())) return null
  return d.getTime()
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export function ReschedulePopover({ repair, open, onConfirm, onCancel }: ReschedulePopoverProps) {
  const anchorEpoch = getDateAnchor({ plannedDate: repair.plannedDate, createdAt: repair.createdAt })
  const [dateValue, setDateValue] = useState<string>(epochToDateInput(anchorEpoch))
  const [isSaving, setIsSaving] = useState(false)

  // Reset date value when the popover opens or repair changes
  useEffect(() => {
    if (open) {
      const currentAnchor = getDateAnchor({ plannedDate: repair.plannedDate, createdAt: repair.createdAt })
      setDateValue(epochToDateInput(currentAnchor))
      setIsSaving(false)
    }
  }, [open, repair.id, repair.plannedDate, repair.createdAt])

  if (!open) return null

  const originalEpoch = getDateAnchor({ plannedDate: repair.plannedDate, createdAt: repair.createdAt })
  const newEpoch = dateInputToEpoch(dateValue)
  const hasChanged = newEpoch !== null && newEpoch !== originalEpoch

  const handleConfirm = async () => {
    if (!hasChanged || !newEpoch) return

    setIsSaving(true)
    try {
      await updateRepairNotes(repair.id, { plannedDate: newEpoch })
      onConfirm()
    } catch {
      // Silently fail — user can retry. In production, show a toast.
    } finally {
      setIsSaving(false)
    }
  }

  return (
    <div className="absolute z-50 mt-1 w-[220px] rounded-lg border bg-popover p-3 shadow-lg">
      <div className="space-y-2">
        {/* Date Input */}
        <div>
          <label className="block text-xs font-medium text-muted-foreground mb-1">
            New planned date
          </label>
          <input
            type="date"
            value={dateValue}
            onChange={(e) => setDateValue(e.target.value)}
            className="w-full px-2 py-1.5 text-sm border rounded-md bg-background focus:outline-none focus:ring-2 focus:ring-ring"
          />
        </div>

        {/* Buttons */}
        <div className="flex gap-2 justify-end">
          <button
            type="button"
            onClick={onCancel}
            disabled={isSaving}
            className="px-3 py-1.5 text-xs font-medium rounded-md border hover:bg-muted transition-colors disabled:opacity-50"
          >
            Cancel
          </button>
          <button
            type="button"
            onClick={handleConfirm}
            disabled={!hasChanged || isSaving}
            className="px-3 py-1.5 text-xs font-medium rounded-md bg-primary text-primary-foreground hover:bg-primary/90 transition-colors disabled:opacity-50"
          >
            {isSaving ? 'Saving...' : 'Confirm'}
          </button>
        </div>
      </div>
    </div>
  )
}

/**
 * RepairCard — Standard-density card for the week calendar view.
 *
 * Shows: customer name, bicycle model, status badge (STATUS_COLORS),
 * assigned worker name, and pickup day indicator when applicable.
 * Card body click navigates to repair detail page.
 * Calendar icon button opens inline reschedule popover.
 */

import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { User, Calendar } from 'lucide-react'
import type { RepairDetailWithCustomer } from '../types.js'
import { STATUS_COLORS } from '../types.js'
import { ReschedulePopover } from './ReschedulePopover.js'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface WorkerOption {
  id: string
  name: string
}

interface RepairCardProps {
  repair: RepairDetailWithCustomer
  workers: WorkerOption[]
  /** Called when the reschedule popover confirms a date change. Triggers parent refetch. */
  onReschedule?: () => void
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function getWorkerName(assignedTo: string | null, workers: WorkerOption[]): string {
  if (!assignedTo) return 'Unassigned'
  const worker = workers.find((w) => w.id === assignedTo)
  return worker?.name ?? 'Unknown'
}

function formatStatus(status: RepairDetailWithCustomer['status']): string {
  return status.replace('_', ' ').replace(/\b\w/g, (c) => c.toUpperCase())
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export function RepairCard({ repair, workers, onReschedule }: RepairCardProps) {
  const navigate = useNavigate()
  const [showPopover, setShowPopover] = useState(false)

  const handleClick = () => {
    navigate(`/repairs/${repair.id}`)
  }

  return (
    <div className="relative">
      <div
        role="link"
        tabIndex={0}
        onClick={handleClick}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault()
            handleClick()
          }
        }}
        className={`group cursor-pointer rounded-lg border bg-card p-3 transition-colors hover:bg-muted/50 hover:border-primary/50 ${STATUS_COLORS[repair.status].split(' ')[0]}/10`}
      >
        {/* Status Badge */}
        <div className="mb-2">
          <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${STATUS_COLORS[repair.status]}`}>
            {formatStatus(repair.status)}
          </span>
        </div>

        {/* Customer Name */}
        <div className="text-sm font-semibold text-foreground mb-1">
          {repair.customerName || '—'}
        </div>

        {/* Bicycle Info */}
        <div className="text-xs text-muted-foreground mb-2">
          {repair.bicycleBrand} {repair.bicycleModel}
          {repair.bicycleColor ? ` · ${repair.bicycleColor}` : ''}
        </div>

        {/* Assigned Worker */}
        <div className="flex items-center gap-1.5 text-xs text-muted-foreground mb-2">
          <User size={12} />
          {getWorkerName(repair.assignedTo, workers)}
        </div>

        {/* Pickup Day Indicator */}
        {repair.pickupDate != null && (
          <div className="flex items-center gap-1.5 text-xs">
            <span className="inline-block w-2 h-2 rounded-full bg-blue-500" />
            <span className="text-muted-foreground flex items-center gap-1">
              <Calendar size={10} />
              pickup scheduled
            </span>
          </div>
        )}

        {/* Reschedule Button — top-right corner */}
        <button
          type="button"
          onClick={(e) => {
            e.stopPropagation()
            setShowPopover(true)
          }}
          className="absolute top-2 right-2 p-1 rounded-md opacity-0 group-hover:opacity-100 transition-opacity hover:bg-muted text-muted-foreground hover:text-foreground"
          aria-label="Reschedule repair"
        >
          <Calendar size={14} />
        </button>
      </div>

      {/* Inline Reschedule Popover */}
      {showPopover && (
        <ReschedulePopover
          repair={repair}
          open={showPopover}
          onConfirm={() => {
            setShowPopover(false)
            onReschedule?.()
          }}
          onCancel={() => setShowPopover(false)}
        />
      )}
    </div>
  )
}

/**
 * Repair feature API client.
 */

import type {
  RepairDetail,
  RepairDetailWithCustomer,
  CustomerWithBicycles,
} from './types.js'

// ---------------------------------------------------------------------------
// Types for request/response shapes
// ---------------------------------------------------------------------------

export interface PaginatedRepairs {
  repairs: RepairDetailWithCustomer[]
  total: number
  page: number
  pageSize: number
  totalPages: number
}

interface RepairIntakeInput {
  customerMode: 'existing' | 'new'
  existingCustomerId?: string
  newCustomer?: {
    firstName?: string
    lastName?: string
    companyName?: string
    phone: string
    email?: string
  }
  bicycleMode: 'select_existing' | 'create_new'
  existingBicycleId?: string
  newBicycle?: {
    brand: string
    model: string
    color: string
  }
  customerNotes: string
  plannedDate?: number | null
  pickupDate?: number | null
}

interface StatusTransitionInput {
  targetStatus: RepairDetail['status']
  holdReason?: 'waiting_parts' | 'awaiting_customer_approval' | 'other'
  holdReasonNote?: string
}

interface NotesUpdateInput {
  customerNotes?: string | null
  internalNotes?: string | null
  plannedDate?: number | null
  pickupDate?: number | null
}

// ---------------------------------------------------------------------------
// API Functions
// ---------------------------------------------------------------------------

/** Create a new repair via the intake flow. */
export async function createRepair(input: RepairIntakeInput): Promise<RepairDetail> {
  const response = await fetch('/api/repairs', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to create repair' }))
    throw new Error(error.error || 'Failed to create repair')
  }

  return response.json()
}

/** Get a single repair by ID. */
export async function getRepair(id: string): Promise<RepairDetail> {
  const response = await fetch(`/api/repairs/${id}`)

  if (!response.ok) {
    throw new Error('Failed to fetch repair')
  }

  return response.json()
}

/** Transition a repair's status. */
export async function transitionRepairStatus(id: string, input: StatusTransitionInput): Promise<RepairDetail> {
  const response = await fetch(`/api/repairs/${id}/transition`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to transition status' }))
    throw new Error(error.error || 'Failed to transition status')
  }

  return response.json()
}

/** Update repair notes. */
export async function updateRepairNotes(id: string, input: NotesUpdateInput): Promise<RepairDetail> {
  const response = await fetch(`/api/repairs/${id}/notes`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to update notes' }))
    throw new Error(error.error || 'Failed to update notes')
  }

  return response.json()
}

/** Get a customer with their bicycles for intake selection. */
export async function getCustomerWithBicycles(customerId: string): Promise<CustomerWithBicycles> {
  const response = await fetch(`/api/repairs/customers/${customerId}`)

  if (!response.ok) {
    throw new Error('Failed to fetch customer with bicycles')
  }

  return response.json()
}

// ---------------------------------------------------------------------------
// Timer API — POST /repairs/:id/timer/start & stop
// ---------------------------------------------------------------------------

export interface WorkLog {
  id: string
  repairId: string
  userId: string
  startedAt: number | null
  endedAt: number | null
  durationMs?: number
}

/** Start a manual work timer for a repair. Returns the created work log. */
export async function startWorkTimer(repairId: string, userId: string): Promise<WorkLog> {
  const response = await fetch(`/api/repairs/${repairId}/timer/start`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ userId }),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to start timer' }))
    throw new Error(error.error || 'Failed to start work timer')
  }

  return response.json()
}

/** Stop an active work timer session. Returns the updated work log with duration. */
export async function stopWorkTimer(repairId: string, workLogId: string): Promise<WorkLog> {
  const response = await fetch(`/api/repairs/${repairId}/timer/stop`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ workLogId }),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to stop timer' }))
    throw new Error(error.error || 'Failed to stop work timer')
  }

  return response.json()
}

// ---------------------------------------------------------------------------
// Repair List API — GET /repairs
// ---------------------------------------------------------------------------

interface RepairListFilters {
  status?: string
  assignedTo?: string
  pickupDate?: 'today' | 'this_week'
  page?: number
  pageSize?: number
}

/** Get paginated repair list with optional filters. */
export async function getRepairs(filters: RepairListFilters = {}): Promise<PaginatedRepairs> {
  const params = new URLSearchParams()

  if (filters.status) params.set('status', filters.status)
  if (filters.assignedTo === 'unassigned') params.set('assignedTo', 'unassigned')
  else if (filters.assignedTo) params.set('assignedTo', filters.assignedTo)
  if (filters.pickupDate) params.set('pickupDate', filters.pickupDate)
  params.set('page', String(filters.page ?? 1))
  params.set('pageSize', String(filters.pageSize ?? 20))

  const response = await fetch(`/api/repairs?${params.toString()}`)

  if (!response.ok) {
    throw new Error('Failed to fetch repairs list')
  }

  return response.json()
}

// ---------------------------------------------------------------------------
// Payment Completion API — POST /repairs/:id/complete
// ---------------------------------------------------------------------------

export interface RepairPaymentMethod {
  method: 'cash' | 'card'
  amount: number
}

export interface CompleteRepairInput {
  payments: RepairPaymentMethod[]
}

export interface CompleteRepairResult {
  repair: {
    id: string
    bicycleId: string
    assignedTo: string | null
    status: 'completed'
    customerNotes: string | null
    internalNotes: string | null
    holdReason: string | null
    holdReasonNote: string | null
    plannedDate: number | null
    pickupDate: number | null
    completedAt: number | null
    createdAt: number
  }
  sale: {
    id: string
    saleNumber: string
    customerId: string | null
    sourceType: 'direct_sale' | 'repair' | 'customer_order' | 'backorder'
    sourceId: string | null
    status: 'completed' | 'voided'
    subtotalNet: number
    vatTotal: number
    totalGross: number
  }
  payments: Array<{
    id: string
    method: 'cash' | 'card' | 'bank_transfer'
    amount: number
  }>
  stockMovements: Array<{
    id: string
    partId: string
    quantityDelta: number
    reason: string
    referenceType: string
    referenceId: string
  }>
}

/**
 * Complete a repair with payment data (single or split methods).
 *
 * Atomic transaction: validates → deducts stock → creates linked sale → marks completed.
 */
export async function completeRepairPayment(
  repairId: string,
  input: CompleteRepairInput,
): Promise<CompleteRepairResult> {
  const response = await fetch(`/api/repairs/${repairId}/complete`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Payment completion failed' }))
    throw new Error(error.error || `Failed to complete repair (status ${response.status})`)
  }

  return response.json() as Promise<CompleteRepairResult>
}

// ---------------------------------------------------------------------------
// Week Calendar API — GET /repairs?from=&to=&statusIn=
// ---------------------------------------------------------------------------

/** Active statuses shown on the week calendar */
const ACTIVE_STATUSES = ['in_progress', 'on_hold', 'verified', 'ready'] as const

/**
 * Fetch repairs for a date range (week). Filters by active statuses only.
 *
 * @param from — Inclusive epoch-ms lower bound
 * @param to — Inclusive epoch-ms upper bound
 */
export async function getRepairsForWeek(from: number, to: number): Promise<PaginatedRepairs> {
  const statusIn = ACTIVE_STATUSES.join(',')
  const params = new URLSearchParams()
  params.set('from', String(from))
  params.set('to', String(to))
  params.set('statusIn', statusIn)
  params.set('page', '1')
  params.set('pageSize', '100') // calendar needs all repairs for the week

  const response = await fetch(`/api/repairs?${params.toString()}`)

  if (!response.ok) {
    throw new Error('Failed to fetch repairs for week')
  }

  return response.json()
}

/**
 * Repair feature types — mirrors shared types for frontend use.
 */

// ============================================================================
// Repair Status
// ============================================================================

export type RepairStatus = 'intake' | 'in_progress' | 'on_hold' | 'verified' | 'ready' | 'completed' | 'cancelled'

/** Color mapping for status badges */
export const STATUS_COLORS: Record<RepairStatus, string> = {
  intake: 'bg-blue-100 text-blue-800',
  in_progress: 'bg-yellow-100 text-yellow-800',
  on_hold: 'bg-orange-100 text-orange-800',
  verified: 'bg-purple-100 text-purple-800',
  ready: 'bg-green-100 text-green-800',
  completed: 'bg-gray-100 text-gray-800',
  cancelled: 'bg-red-100 text-red-800',
}

// ============================================================================
// Repair Detail Shape (matches API response)
// ============================================================================

export interface RepairDetail {
  id: string
  bicycleId: string
  assignedTo: string | null
  status: RepairStatus
  customerNotes: string | null
  internalNotes: string | null
  holdReason: 'waiting_parts' | 'awaiting_customer_approval' | 'other' | null
  holdReasonNote: string | null
  plannedDate: number | null
  pickupDate: number | null
  completedAt: number | null
  createdAt: number
}

/** Repair detail enriched with customer name and bicycle info for list display */
export interface RepairDetailWithCustomer extends Omit<RepairDetail, 'bicycleId'> {
  customerName: string | null
  bicycleBrand: string
  bicycleModel: string
  bicycleColor: string | null
}

// ============================================================================
// Intake Form Types
// ============================================================================

/** Customer selection mode */
export type CustomerMode = 'existing' | 'new'

/** Bicycle selection mode */
export type BicycleMode = 'select_existing' | 'create_new'

/** Compact customer shape for selectors — matches GET /api/customers response. */
export interface IntakeCustomer {
  id: string
  displayName: string
  type: 'private' | 'company'
}

/** Compact bicycle shape for selectors */
export interface IntakeBicycle {
  id: string
  brand: string
  model: string
  color: string | null
  year: number | null
}

/** Customer with their bicycles — returned during intake lookup */
export interface CustomerWithBicycles extends IntakeCustomer {
  bicycles: IntakeBicycle[]
}

/** Form data for the repair intake modal */
export interface RepairIntakeFormData {
  // Customer section
  customerMode: CustomerMode
  existingCustomerId?: string
  newFirstName?: string
  newLastName?: string
  newCompanyName?: string
  newPhone: string
  newEmail: string

  // Bicycle section
  bicycleMode: BicycleMode
  existingBicycleId?: string
  newBrand: string
  newModel: string
  newColor: string

  // Notes
  customerNotes: string

  // Optional scheduling dates (epoch ms, nullable)
  plannedDate?: number | null
  pickupDate?: number | null
}

/** Default empty form state */
export const createEmptyIntakeForm = (): RepairIntakeFormData => ({
  customerMode: 'existing',
  newPhone: '',
  newEmail: '',
  bicycleMode: 'select_existing',
  newBrand: '',
  newModel: '',
  newColor: '',
  customerNotes: '',
})

/**
 * Date anchor utility.
 *
 * Resolves a repair's display date for calendar placement:
 * - Primary: plannedDate (epoch ms)
 * - Fallback: createdAt when plannedDate is null/undefined
 */

export interface DateAnchorInput {
  plannedDate: number | null | undefined
  createdAt: number
}

/**
 * Returns the epoch-ms timestamp to anchor a repair card on the calendar.
 * Uses plannedDate if present; falls back to createdAt.
 */
export function getDateAnchor(input: DateAnchorInput): number {
  return input.plannedDate ?? input.createdAt
}

/**
 * ReschedulePopover — Component tests.
 *
 * Verifies:
 * - Renders date input and confirm/cancel buttons when open
 * - Does not render anything when closed
 * - Confirm sends PATCH to updateRepairNotes with new plannedDate
 * - Calls onConfirm callback after successful save
 * - Calls onCancel callback when cancel is clicked
 */

import { describe, it, expect, vi, afterEach } from 'vitest'
import { render, screen, fireEvent, waitFor } from '@testing-library/react'
import type { RepairDetailWithCustomer } from '../../types.js'
import { ReschedulePopover } from '../ReschedulePopover.js'

// ---------------------------------------------------------------------------
// Mock the API module — hoisted to top of file for vi.mock
// ---------------------------------------------------------------------------

const mockUpdateRepairNotes = vi.fn() as ReturnType<typeof vi.fn> & {
  mockResolvedValueOnce: (value: RepairDetailWithCustomer) => void
}

vi.mock('../../api.js', () => ({
  updateRepairNotes: (...args: unknown[]) => mockUpdateRepairNotes(...args),
}))

// ---------------------------------------------------------------------------
// Test fixtures
// ---------------------------------------------------------------------------

function createRepair(overrides?: Partial<RepairDetailWithCustomer>): RepairDetailWithCustomer {
  return {
    id: 'repair-001',
    assignedTo: null,
    status: 'in_progress',
    customerNotes: null,
    internalNotes: null,
    holdReason: null,
    holdReasonNote: null,
    plannedDate: 1706832000000, // Feb 2, 2024
    pickupDate: null,
    completedAt: null,
    createdAt: 1706745600000,
    customerName: 'Jane Doe',
    bicycleBrand: 'Trek',
    bicycleModel: 'Domane SL',
    bicycleColor: 'blue',
    ...overrides,
  }
}

function renderPopover(
  repair?: RepairDetailWithCustomer,
  props?: { onConfirm?: () => void; onCancel?: () => void },
) {
  const r = repair ?? createRepair()
  return render(
    <ReschedulePopover
      repair={r}
      open={true}
      onConfirm={props?.onConfirm ?? vi.fn()}
      onCancel={props?.onCancel ?? vi.fn()}
    />,
  )
}

// ---------------------------------------------------------------------------
// Tests: Rendering
// ---------------------------------------------------------------------------

describe('ReschedulePopover — rendering', () => {
  afterEach(() => {
    mockUpdateRepairNotes.mockClear()
  })

  it('renders date input when open', () => {
    const { container } = renderPopover()
    expect(container.querySelector('input[type="date"]')).toBeInTheDocument()
  })

  it('renders confirm button', () => {
    renderPopover()
    expect(screen.getByText(/confirm/i)).toBeInTheDocument()
  })

  it('renders cancel button', () => {
    renderPopover()
    expect(screen.getByText(/cancel/i)).toBeInTheDocument()
  })

  it('pre-fills date input with current plannedDate', () => {
    const repair = createRepair({ plannedDate: 1706832000000 }) // Feb 2, 2024
    const { container } = renderPopover(repair)
    const input = container.querySelector('input[type="date"]') as HTMLInputElement
    expect(input.value).toBe('2024-02-02')
  })

  it('pre-fills date input with createdAt fallback when plannedDate is null', () => {
    const repair = createRepair({ plannedDate: null, createdAt: 1706745600000 }) // Feb 1, 2024
    const { container } = renderPopover(repair)
    const input = container.querySelector('input[type="date"]') as HTMLInputElement
    expect(input.value).toBe('2024-02-01')
  })

  it('does not render anything when open is false', () => {
    const { container } = render(
      <ReschedulePopover
        repair={createRepair()}
        open={false}
        onConfirm={vi.fn()}
        onCancel={vi.fn()}
      />,
    )
    expect(container.innerHTML).toBe('')
  })
})

// ---------------------------------------------------------------------------
// Tests: Cancel behavior
// ---------------------------------------------------------------------------

describe('ReschedulePopover — cancel', () => {
  afterEach(() => {
    mockUpdateRepairNotes.mockClear()
  })

  it('calls onCancel when cancel button is clicked', () => {
    const mockCancel = vi.fn()
    renderPopover(createRepair(), { onCancel: mockCancel })

    fireEvent.click(screen.getByText(/cancel/i))
    expect(mockCancel).toHaveBeenCalledOnce()
  })

  it('does not call API on cancel', () => {
    renderPopover(createRepair())
    fireEvent.click(screen.getByText(/cancel/i))

    expect(mockUpdateRepairNotes).not.toHaveBeenCalled()
  })
})

// ---------------------------------------------------------------------------
// Tests: Confirm behavior
// ---------------------------------------------------------------------------

describe('ReschedulePopover — confirm', () => {
  afterEach(() => {
    mockUpdateRepairNotes.mockClear()
  })

  it('sends PATCH with new plannedDate when date is changed and confirmed', async () => {
    const mockConfirm = vi.fn()
