/** Validate that a status transition is allowed by the state machine. */
function validateTransition(from: RepairStatus, to: RepairStatus): void {
  // Cancel is always allowed from non-terminal states
  if (to === 'cancelled' && CANCEL_TARGETS.includes(from)) {
    return
  }

  const allowed = VALID_TRANSITIONS[from]
  if (!allowed || !allowed.includes(to)) {
    throw new InvalidStatusTransitionError(from, to)
  }
}

